import time
import re

from threading import Thread

from imap_tools import MailBox, AND
from typing import Optional

from ..admin.methods import Client
from ..tracer import tracer

event_response = None


__all__ = ["AdminClient"]


class AdminClient(Client):
    def __init__(
        self,
        fix_otp: str = "ONPREM",
        uin: Optional[str] = None,
        email_url: Optional[str] = None,
        email_password: Optional[str] = None,
        *args,
        **kwargs,
    ):
        super(Client, self).__init__(*args, **kwargs)
        self.uin = uin
        self.email_url = email_url
        self.email_password = email_password
        self.fix_otp = fix_otp

    @tracer.start_as_current_span("admin.get_otp_token")
    def get_otp_token(self, login: str, exec_local: bool = True) -> str:
        if self.env == "SANDBOX":
            if exec_local:
                return self.get_otp_token_from_chat_local(login)
            else:
                return self.get_otp_token_from_chat(login)

        elif self.env in ["VKTI", "PRE_VKTI", "TARM", "PRE_TARM", "SAAS", "PRE_SAAS"]:
            return self.get_otp_token_from_mail_local(
                password=self.email_password,
                imap_url=self.email_url,
            )

        else:
            raise ValueError(f"Unknown env value: {self.env}")

    @tracer.start_as_current_span("admin.get_otp_token_from_mail_local")
    def get_otp_token_from_mail_local(self, password: str, imap_url: str):
        self.logger.debug(f"password: {password}, imap_url: {imap_url}")

        with MailBox(imap_url).login(username=self.uin, password=password) as mailbox:
            for msg in mailbox.fetch(AND(seen=False)):
                self.logger.debug(msg)

        otp_token = None

        with MailBox(imap_url).login(username=self.uin, password=password) as mailbox:
            for i in range(5):
                for msg in mailbox.fetch(AND(seen=False)):
                    self.logger.info(f"{msg.date} - {msg.subject}: {msg.text}")
                    otp_token = re.findall(r"[A-Z0-9]{6}", msg.text)[-1]
                if otp_token is not None:
                    self.logger.info(f"OTP Token: {otp_token}")
                    break
                time.sleep(i)

            assert otp_token, "OTP Token not found in incoming messages"

        return otp_token

    @tracer.start_as_current_span("admin.get_otp_token_from_chat")
    def get_otp_token_from_chat(self, login: str):
        self.auth_otp_generate(login)
        time.sleep(3)
        response = self.session.post(
            "https://im-qa-helper.mail.msk/api/v1/night/dev/otp",
            params={"uin": login},
        )
        response.encoding = "utf-8"
        response = response.json()

        return response["token"]

    @tracer.start_as_current_span("admin.get_otp_token_from_chat_local")
    def get_otp_token_from_chat_local(self, login: str):
        def get_events():
            global event_response

            event_response = self.session.get(
                url="https://api.internal.myteam.mail.ru/bot/v1/events/get",
                params={
                    "token": "001.2731743155.3227401719:1000001264",
                    "lastEventId": 0,
                    "pollTime": 30,
                },
            ).json()

        local_thread = Thread(target=get_events)

        local_thread.start()

        self.auth_otp_generate(login)

        time.sleep(2)

        for event in reversed(event_response["events"]):
            return event["payload"]["text"].splitlines()[1]
